CREATE TABLE `ts_codeql_runs` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `repository_id` bigint unsigned NOT NULL,
  `workflow` text COLLATE utf8mb4_general_ci,
  `execution_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `workflow_run_id` bigint unsigned DEFAULT NULL,
  `ref_bytes` varbinary(1024) DEFAULT NULL,
  `sha` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` datetime(6) NOT NULL,
  `updated_at` datetime(6) NOT NULL,
  `status` tinyint unsigned NOT NULL DEFAULT '0',
  `actor_login` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `actor_grid` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `triggering_event` tinyint unsigned NOT NULL DEFAULT '0',
  `codeql_config_id` bigint DEFAULT NULL,
  `run_type` tinyint unsigned NOT NULL DEFAULT '0',
  `action_inputs` json DEFAULT NULL,
  `codeql_packs` text COLLATE utf8mb4_unicode_520_ci DEFAULT NULL,
  `event_timestamp` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `index_codeql_runs_on_workflow_run_id` (`workflow_run_id`),
  KEY `index_codeql_runs_on_repository_id_event_created_at` (`repository_id`, `triggering_event`, `created_at`),
  KEY `index_codeql_runs_on_run_type_status_and_updated_at` (`run_type`,`status`, `updated_at`),
  KEY `index_codeql_runs_on_repository_id_and_sha` (`repository_id`, `sha`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
